Plain LDA (no shrinkage) gives 0.76 leave-one-out, shrinking to identity hurts. Next I test shrinking toward the diagonal, small ridge, equal priors, and kNN as comparisons.
```python
X=np.load("train_x.npy"); y=np.load("train_y.npy")
def lda(Xt,yt,lam,mode,prior=True):
    M=np.array([Xt[yt==c].mean(0) for c in range(4)])
    R=Xt-M[yt]; S=R.T@R/(len(Xt)-4)
    T=np.diag(np.diag(S)) if mode=='diag' else np.eye(18)*np.trace(S)/18
    S=(1-lam)*S+lam*T
    W=np.linalg.solve(S,M.T).T; b=-0.5*np.sum(W*M,1)
    if prior: b+=np.log(np.bincount(yt,minlength=4)/len(yt))
    return W,b
def loo(f):
    ok=0
    for i in range(len(X)):
        m=np.arange(len(X))!=i; W,b=f(X[m],y[m]); ok+=np.argmax(W@X[i]+b)==y[i]
    return ok/len(X)
for lam in [0,0.005,0.01,0.02,0.05]:
    print('diag',lam, loo(lambda a,b_:lda(a,b_,lam,'diag')), 'eqprior', loo(lambda a,b_:lda(a,b_,lam,'diag',False)))
D=((X[:,None]-X[None])**2).sum(-1); np.fill_diagonal(D,1e9)
for k in [1,3,5,7]:
    nn=np.argsort(D,1)[:,:k]; pred=[np.bincount(y[r],minlength=4).argmax() for r in nn]; print('knn',k,np.mean(np.array(pred)==y))
